import{_ as e,o as i,c as t,ag as c}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-11-06（生物医学 · 肝转移「劫持」造血压制免疫）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-11-06-biomed.md","filePath":"topics/biomedicine/science-daily-2026-11-06-biomed.md"}'),n={name:"topics/biomedicine/science-daily-2026-11-06-biomed.md"};function s(r,o,d,a,l,g){return i(),t("div",null,[...o[0]||(o[0]=[c('<h1 id="科学日报-·-2026-11-06-生物医学-·-肝转移「劫持」造血压制免疫" tabindex="-1">科学日报 · 2026-11-06（生物医学 · 肝转移「劫持」造血压制免疫） <a class="header-anchor" href="#科学日报-·-2026-11-06-生物医学-·-肝转移「劫持」造血压制免疫" aria-label="Permalink to &quot;科学日报 · 2026-11-06（生物医学 · 肝转移「劫持」造血压制免疫）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-06.md</code> — 第56期 ｜ 科学板块（生物向 1 篇） 落盘说明：文件名带 <code>-biomed</code> 后缀，避免与其它主题同日同名文件互引产生伪边。</p></blockquote><hr><h2 id="科学日报-2026-11-06-生物-·-1-1-肝转移为什么能让全身免疫「失能」" tabindex="-1">科学日报 2026-11-06（生物 · 1/1）：肝转移为什么能让全身免疫「失能」 <a class="header-anchor" href="#科学日报-2026-11-06-生物-·-1-1-肝转移为什么能让全身免疫「失能」" aria-label="Permalink to &quot;科学日报 2026-11-06（生物 · 1/1）：肝转移为什么能让全身免疫「失能」&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-06.md</code> ｜ DOI: 10.1126/science.aea3046 ｜ Science (2026)</p></blockquote><ul><li>问题：肿瘤相关<strong>造血异常</strong>会造成<strong>全身免疫抑制</strong>；但<strong>肿瘤能否主动在局部（肝脏）启动髓外造血来压制抗肿瘤免疫</strong>，此前不清楚。</li><li>方法：鉴定<strong>肝转移相关造血干细胞（LM-HSC）</strong>，刻画其来源、分化与下游效应，追出从「招募 HSC」到「免疫细胞无能」的完整链条。</li><li>结果（实测）： <ul><li>肝转移灶建立<strong>异位门脉周（periportal）造血生态位</strong>，经<strong>库普弗细胞依赖的 CCR1 信号</strong>招募骨髓 HSC；</li><li>LM-HSC <strong>保留自我更新与多能性</strong>，但 <strong>CREB 激活</strong>把分化<strong>偏向髓系</strong>，尤其产出 <strong>ANXA1⁺ 的未成熟中性粒细胞</strong>；</li><li>这些中性粒细胞<strong>分泌糖皮质激素</strong>，以<strong>旁分泌</strong>方式激活 <strong>CD8⁺T 细胞与 NK 细胞</strong>的<strong>糖皮质激素受体信号</strong>，诱导<strong>免疫检查点受体表达与功能性无能</strong>。</li></ul></li><li>洞察（对本库 <code>biomedicine</code> × <code>ai-system-architecture</code>）： <ol><li><strong>「肿瘤不是躲免疫，而是把免疫的『生产端』改造了」</strong>——它不直接灭杀 T 细胞，而是<strong>霸占造血生态位、改变新免疫细胞的『出厂设置』</strong>；判据：<strong>当某系统持续输出『坏结果』时，检查它的供给端/生产端是否已被改写</strong>（呼应母题「<strong>环境结构 &gt; 个体微调</strong>」——改生态位比逐个纠正细胞更致命）。</li><li><strong>「旁分泌的激素是全局开关」</strong>——由局部中性粒细胞放出的糖皮质激素，落到远处 T/NK 上造成广泛失能；判据：<strong>局部病灶可以借『可扩散信号』产生全身效应</strong>。</li><li><strong>与库内呼应</strong>：与 <code>topics/biomedicine/science-daily-2026-10-27-biomed.md</code>（内脏脂肪纤维化—炎症亚群、TGFβ）等「<strong>生态位与免疫抑制</strong>」主题同族；潜在<strong>靶点</strong>为 CCR1 / CREB / ANXA1⁺ 中性粒细胞 / 糖皮质激素受体轴。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ <code>topics/biomedicine/2026-q3-breakthroughs.md</code> ｜ 第56期 科学板块</p></blockquote><p>关键词：科学日报第56期、肝转移liver metastasis、髓外造血extramedullary hematopoiesis、造血生态位hematopoietic niche、LM-HSC肝转移相关造血干细胞、库普弗细胞Kupffer cell、CCR1、CREB、髓系分化、ANXA1阳性未成熟中性粒细胞、糖皮质激素glucocorticoid、旁分泌paracrine、CD8阳性T细胞、自然杀伤细胞NK、免疫检查点受体、功能性无能anergy、免疫抑制、改供给端而非灭杀、环境结构大于个体微调</p><p>关联：<code>topics/biomedicine/index.md</code>、<code>topics/biomedicine/science-daily-2026-10-27-biomed.md</code>、<code>topics/biomedicine/science-daily-2026-11-05-biomed.md</code>、<code>topics/neuroscience/index.md</code>、<code>ScienceDaily/daily/2026-11-06.md</code></p>',10)])])}const b=e(n,[["render",s]]);export{p as __pageData,b as default};
